import XCTest
@testable import LKSync
@testable import LKStore

/// C03 – importing the Capacitor export must give exactly what the web Store reads back (vectors/migration.json, generated by loading each
/// export into the real web/js/core.js Store). Cards the web compacts with its word library (L:1, M3 bundles the lexicon natively) are checked
/// field by field: every field of the expected slim card must be identical in ours.
final class MigrationTests: XCTestCase {
    lazy var v: JSON = (try? Vectors.load("migration.json")) ?? .null

    func compare(_ name: String, got: SyncDoc, meta: SyncMetaState, expect: JSON) {
        let want = expect.object ?? [:]
        let mine = got.vectorJSON()
        for (k, w) in want {
            switch k {
            case "cards":
                let gc = mine["cards"]?.object ?? [:], wc = w.object ?? [:]
                XCTAssertEqual(Set(gc.keys), Set(wc.keys), "«\(name)» card keys")
                for (key, wcard) in wc {
                    guard let g = gc[key] else { continue }
                    if JSON.num(wcard["L"]) == 1 {
                        for (f, x) in wcard.object ?? [:] where f != "L" {
                            if let d = jsonDiff(g[f], x, path: "cards.\(key).\(f)") { XCTFail("«\(name)» \(d)") }
                        }
                    } else if let d = jsonDiff(g, wcard, path: "cards.\(key)") { XCTFail("«\(name)» \(d)") }
                }
            case "pulledHashes":
                let p: JSON = .object(meta.pulledHashes.mapValues { .object($0.mapValues { .string($0) }) })
                if let d = jsonDiff(p, w, path: k) { XCTFail("«\(name)» \(d)") }
            default:
                if let d = jsonDiff(mine[k], w, path: k) { XCTFail("«\(name)» \(d)") }
            }
        }
    }

    /// Import half of C03 against every vector case, through the real SwiftData repository (in memory).
    func testParityC03() async throws {
        let now = JSON.num(v["now"])
        let cases = v["cases"]?.array ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 5, "migration.json cases")
        for c in cases {
            let name = c["name"]?.string ?? "?"
            let imp = try MigrationImport(export: c["export"]!, now: now)
            compare(name + " (import)", got: imp.doc, meta: imp.syncMeta, expect: c["expect"]!)
            let repo = try LKRepository.inMemory()
            try await repo.importLegacy(imp, now: now)
            let doc = try await repo.snapshot(), meta = await repo.loadMeta(), at = await repo.migratedAt()
            compare(name + " (SwiftData)", got: doc, meta: meta, expect: c["expect"]!)
            XCTAssertEqual(at, now, "«\(name)» marked migrated")
            // idempotent: a second run (e.g. crash after import, before marking) neither loses nor duplicates anything
            try await repo.importLegacy(imp, now: now)
            let again = try await repo.snapshot()
            XCTAssertEqual(Set(again.cards.keys), Set(doc.cards.keys), "«\(name)» re-import")
        }
    }

    /// Nothing outside the sync document is dropped: every other export key is kept verbatim.
    func testLegacyKeysKept() throws {
        let export: JSON = ["kind": "lexkite-capacitor-export", "v": 1, "prefix": "ielts.", "at": 1,
                            "idb": ["lexkite": ["ielts.cards": [:], "ielts.sentences": ["s": 1]]],
                            "ls": ["ielts.mistakes": #"[{"w":"a","fixed":false}]"#, "vb.uiLang": "vi", "ielts.stats": #"{"days":{"2026-01-01":3}}"#]]
        let imp = try MigrationImport(export: export, now: 10)
        XCTAssertEqual(imp.legacy["ls:ielts.mistakes"], .string(#"[{"w":"a","fixed":false}]"#))
        XCTAssertEqual(imp.legacy["ls:vb.uiLang"], "vi")
        XCTAssertEqual(imp.legacy["idb:lexkite/ielts.sentences"], ["s": 1])
        XCTAssertNil(imp.legacy["ls:ielts.stats"], "stats is part of the document, not legacy")
        XCTAssertEqual(imp.doc.stats?["days"]?["2026-01-01"], 3)
    }

    func testRejectsForeignExport() {
        XCTAssertThrowsError(try MigrationImport(export: ["kind": "something-else"], now: 1))
        XCTAssertThrowsError(try MigrationImport(export: "nope", now: 1))
    }

    func testKeyRules() throws {
        // contract.json x-lexkite.keys (generated from core.js keyOf/tlKey)
        let contract = try JSON.parse(Data(contentsOf: Vectors.dir.deletingLastPathComponent().appendingPathComponent("contract.json")))
        let keys = contract["x-lexkite"]?["keys"]?.array ?? []
        XCTAssertFalse(keys.isEmpty)
        for k in keys { XCTAssertEqual(MigrationImport.tlKey(k["word"], k["tl"]), k["key"]?.string, k.stableString) }
    }
}
